#!/usr/bin/env python3
"""FS3 v202 - the remaining large ships in 3D, break-up from the models,
points instead of tickets, AI guns that keep firing.

    3D         The Hades, Faustus and Hippocrates, the freighters (Asmodeus,
               Bast, Bes, Chronos, Dis, Ma'at, Mephisto, Poseidon, Satis,
               Triton), the transports (Argo, Azrael, Elysium, Isis), the
               Arcadia, the Unknown Device, the Knossos and the gas miners
               (Anuket, Rahu, Zephyrus) from their MediaVP models, with their
               models' turrets. Moving parts turn (the Knossos ring, the
               Faustus' solar panel, the miners).
    Break-up   A ship drawn from her model breaks into her model's own debris
               pieces, which tumble off and blow apart later.
    Fixes      The Fenris carries her FS2 beams (@GTC Fenris), the Mjolnir
               points her barrel ahead, a 3D hull no longer lies under every
               sprite (M11), nobody fires on a ship we have taken (M38), ships
               docked together jump through one vortex.
    Missions   Wingmen: three Thoth in M1, six in M3 and M6 (Silvio).
    Points     No tickets any more. Points come from the player's own damage:
               hull as it comes off, shield when the ship dies; objectives
               keep their bonus. Calling a ship costs her hull in points,
               what she has left comes back when the wave is won.
    AI guns    Fighters and bombers of both sides keep the trigger down while
               the target is in their cone, with every gun and a weapon
               energy store like the player's; allied bombers fire at the
               bomber beat. The damage a second stays as it was.
    Log        At most one hit per bolt (no rate over 100 %), a new hull is
               not counted as damage.

Needs v201. Edits src/20_render.js, 30_waves.js, 40_world.js, 50_combat.js,
55_arms.js, 58_model3d.js, 59_field3d.js, 60_effects.js, 70_ui.js,
fieldsim.js, callsim.js and docksim.js. New model files: models_v202_*.zip.
Run assemble.py 202 afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v201 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "f3dNodeMats" not in _f:
    sys.exit("Abbruch: erst v201 einspielen.")
if "f3dFieldPrep" in _f:
    sys.exit("Abbruch: v202 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
